window.AUTH=window.AUTH||{};window.AUTH["19-897"]={"d":"19-897","id":"2020/19-897","n":"Johnson v. Guzman Chavez","briefs":[{"k":"petitioner","label":"Brief of petitioners Mattew T. Albence, Acting Director of U.S. Immigration and Customs Enforcement, et al.","date":"2020-08-14","url":"https://www.supremecourt.gov/DocketPDF/19/19-897/150244/20200814154815413_19-897tsUnitedStates.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondents Maria Angelica Guzman Chavez, et al.","date":"2020-11-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-897/159652/20201104151905179_19-897.bs.brief.pdf","side":"res","n":53},{"k":"reply","label":"Reply of petitioners Tony H. Pham, et al.","date":"2020-12-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-897/162749/20201204182029500_19-897rbUnitedStates.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/594us2r63_4f15.pdf","tr":true,"items":[{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"one by which ‘rights or obligations have been determined.’","cite":"520 U.S. 154, 178"}]},{"t":"case","label":"Castro-Cortez v. INS","cite":"239 F.3d 1037","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/239/1037/","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"An objective observer would have asked, and Congress did, just what was the purpose of all of that procedure, all of those punctilious niceties, which can take years to complete, if the person could just step back into the country a few days later and have the roundelay go on?","cite":"239 F.3d 1037, 1054"}]},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"0":"9, 12, 36","2":"20"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"by":{"0":"33, 34","2":"6"},"q":[{"src":"brief","b":2,"text":"would not avoid removal, only removal to [a particular country],","cite":"140 S. Ct. 1959, 1965 n.5"}]},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"by":{"0":"28"}},{"t":"case","label":"Diouf v. Napolitano","cite":"634 F.3d 1081","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/1081/","by":{"0":"7"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"by":{"0":"4, 19","1":"4, 33, 34"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"generally foreclos[ing] discretionary Page relief from Ptheroteromfs Pending of the reinstated oPrduer.b","cite":"548 U. S. 30, 35"}]},{"t":"case","label":"Guerra v. Shanahan","cite":"831 F.3d 59","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/831/59/","by":{"0":"10","1":"45, 47"}},{"t":"case","label":"Guerrero-Sanchez v. Warden York County Prison","cite":"905 F.3d 208","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/905/208/","by":{"0":"7, 10","1":"44, 45, 47"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"by":{"0":"14, 33, 37","2":"7"},"q":[{"src":"brief","b":0,"text":"especially appropriate in the immigration context where officials ‘exer- cise especially sensitive political functions that implicate questions of foreign relations.’","cite":"526 U.S. at 425"},{"src":"brief","b":2,"text":"withholding only bars deporting an alien to a particular country,","cite":"526 U.S. 415, 419"}]},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"0":"4, 14, 16, 32","2":"7"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"0":"3, 31, 34","1":"5, 29, 36, 37","2":"5"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"0":"22"}},{"t":"case","label":"Martinez v. LaRose","cite":"2020 WL 4282158","y":2020,"court":"6th Cir. July 27","by":{"0":"7, 11"}},{"t":"case","label":"Nasrallah v. Barr","cite":"140 S. Ct. 1683","y":2020,"id":"2019/18-1432","sc":1,"by":{"0":"4, 14, 16, 29, 32","1":"5, 24, 36","2":"7, 11, 12"},"q":[{"src":"brief","b":0,"text":"the noncitizen still ‘may be removed at any time to another country where he or she is not likely to be tortured.’","cite":"140 S. Ct. 1683, 1691"},{"src":"brief","b":0,"text":"does not affect the validity of the final order of removal.","cite":"140 S. Ct. 1683, 1691"},{"src":"brief","b":2,"text":"means only that, notwithstanding the order of removal, the noncitizen may not be removed to the designated country,","cite":"140 S. Ct. 1683, 1691"},{"src":"brief","b":2,"text":"does not disturb the final order of removal,","cite":"140 S. Ct. at 1691"},{"src":"argument","who":"Mr. Suri","text":"The only question left to decide is the particular country, but that's a distinct question, as this Court emphasized just last term in Nasrallah."},{"src":"argument","who":"Mr. Suri","text":"The best answer I have is this Court's decision last term in Nasrallah, where the Court said that a removal order's finality is not affected by CAT protection."},{"src":"argument","who":"Mr. Suri","text":"Second, if you think that \"final\" has to have the same meaning across all contexts, you should rule for us because the general definition of \"finality,\" the reinstatement clause, and Nasrallah all indicate that these orders are final."}]},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"0":"3","1":"7, 41"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"‘decision to locate * * * a provision in one subsection rather than another’","cite":"556 U.S. 418, 431"}]},{"t":"case","label":"Padilla-Ramirez v. Bible","cite":"882 F.3d 826","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/826/","by":{"0":"10, 17","1":"45, 47","2":"10, 11, 13"},"q":[{"src":"brief","b":0,"text":"purpose of [withholding-only] proceedings is instead to determine whether the alien is to be removed to a particular country,","cite":"882 F.3d 826, 835"},{"src":"brief","b":2,"text":"[A] removal order undoubtedly is administratively final when it first is executed; if it is reinstated from its original date, it stands to reason that it retains the same administrative finality.","cite":"882 F.3d 826, 831"},{"src":"brief","b":2,"text":"Withholding-only proceedings do not * * * purport to override section 1231(a)(5)’s prohibition on reopening or reviewing a prior removal order. * * * At most, a grant of withholding will only inhibit the order’s execution with respect to a particular country.","cite":"882 F.3d at 832"}]},{"t":"case","label":"Reyes v. Lynch","cite":"2015 WL 5081597","y":2015,"court":"D. Colo. Aug. 28","by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"Such a transitory appearance of new rights [under Section 1226] makes no legal sense.","cite":"2015 WL 5081597"}]},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"by":{"0":"38"}},{"t":"case","label":"Sale v. Haitian Centers Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"by":{"0":"33"}},{"t":"case","label":"Wanjiru v. Holder","cite":"705 F.3d 258","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/258/","by":{"0":"38"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"by":{"0":"25, 26, 30, 34, 35","1":"passim","2":"9, 15, 16"},"q":[{"src":"brief","b":0,"text":"serious administrative needs and concerns inherent in the necessarily extensive [DHS] efforts to enforce this complex statute.","cite":"533 U.S. at 700"},{"src":"brief","b":1,"text":"fails to remove the alien during","cite":"533 U.S. 678, 682"},{"src":"brief","b":1,"text":"[f]reedom from * * * government custody, detention, or other forms of physical restraint.","cite":"533 U.S. at 690"},{"src":"brief","b":2,"text":"doubt[ful] that when Congress shortened the removal period to 90 days in 1996 it believed that all reasonably foreseeable removals could be accomplished in that time.","cite":"533 U.S. 678, 701"},{"src":"brief","b":2,"text":"bears a reasonable relation to the purpose for which the individual was committed.","cite":"533 U.S. at 690"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"a period reasonably necessary to bring about that alien's removal from the United States.","cite":"533 U. S. 678, 689"},{"src":"argument","who":"Mr. Suri","text":"In this case, Your Honor, this was a habeas corpus petition, and the Court in Zadvydas said that such a habeas corpus petition could be heard where the question is whether the government had the authority to detain the alien in the first place."},{"src":"argument","who":"Mr. Suri","text":"That is how the Court read these provisions in Zadvydas, and that's the precedent we've stuck with here."},{"src":"argument","who":"Mr. Suri","text":"Certainly, but the question about detaining people for years doesn't arise in the vast majority of these cases, and, when it does arise, the procedures in Zadvydas will address that problem."}]},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(47)","(a)(47)(B)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 3","1":"24","2":"1, 12"},"q":[{"src":"brief","b":0,"text":"shall become final upon the earlier of—(i) a determination by the Board of Immigration Appeals affirming such order; or (ii) the expiration of the period in which the alien is permitted to seek review of such order by the Board of Immigration Appeals.","cite":"8 U.S.C. 1101(a)(47)"},{"src":"brief","b":1,"text":"the expiration of the period in which the alien is permitted to seek review of such order by the Board of Immigration Appeals.","cite":"8 U.S.C. § 1101(a)(47)(B)"}]},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1)","(g)"],"by":{"0":"3, 3"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)"],"by":{"0":"2, 6"}},{"t":"usc","label":"8 U.S.C. § 1221","url":"https://www.law.cornell.edu/uscode/text/8/1221","by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)","(a)(2)(A)","(c)"],"stext":{"head":"§1226. Apprehension and detention of aliens","paras":[[0,"(a) Arrest, detention, and release"],[0,"On a warrant issued by the Attorney General, an alien may be arrested and detained pending a decision on whether the alien is to be removed from the United States. Except as provided in subsection (c) and pending such decision, the Attorney General—"],[1,"(1) may continue to detain the arrested alien; and"],[1,"(2) may release the alien on—"],[2,"(A) bond of at least $1,500 with security approved by, and containing conditions prescribed by, the Attorney General; or"],[2,"(B) conditional parole; but"],[1,"(3) may not provide the alien with work authorization (including an \"employment authorized\" endorsement or other appropriate work permit), unless the alien is lawfully admitted for permanent residence or otherwise would (without regard to removal proceedings) be provided such authorization."],[0,"(b) Revocation of bond or parole"],[0,"The Attorney General at any time may revoke a bond or parole authorized under subsection (a), rearrest the alien under the original warrant, and detain the alien."],[0,"(c) Detention of criminal aliens"],[0,"(1) Custody"],[1,"The Attorney General shall take into custody any alien who—"],[2,"(A) is inadmissible by reason of having committed any offense covered in section 1182(a)(2) of this title,"],[2,"(B) is deportable by reason of having committed any offense covered in section 1227(a)(2)(A)(ii), (A)(iii), (B), (C), or (D) of this title,"],[2,"(C) is deportable under section 1227(a)(2)(A)(i) of this title on the basis of an offense for which the alien has been sentence 1 to a term of imprisonment of at least 1 year, or"],[2,"(D) is inadmissible under section 1182(a)(3)(B) of this title or deportable under section 1227(a)(4)(B) of this title,"],[1,"when the alien is released, without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense."],[0,"(2) Release"],[1,"The Attorney General may release an alien described in paragraph (1) only if the Attorney General decides pursuant to section 3521 of title 18 that release of the alien from custody is necessary to provide protection to a witness, a potential witness, a person cooperating with an investigation into major criminal activity, or an immediate family member or close associate of a witness, potential witness, or person cooperating with such an investigation, and the alien satisfies the Attorney General that the alien will not pose a danger to the safety of other persons or of property and is likely to appear for any scheduled proceeding. A decision relating to such release shall take place in accordance with a procedure that considers the severity of the offense committed by the alien."],[0,"(d) Identification of criminal aliens"],[0,"(1) The Attorney General shall devise and implement a system—"],[1,"(A) to make available, daily (on a 24-hour basis), to Federal, State, and local authorities the investigative resources of the Service to determine whether individuals arrested by such authorities for aggravated felonies are aliens;"],[1,"(B) to designate and train officers and employees of the Service to serve as a liaison to Federal, State, and local law enforcement and correctional agencies and courts with respect to the arrest, conviction, and release of any alien charged with an aggravated felony; and"],[1,"(C) which uses computer resources to maintain a current record of aliens who have been convicted of an aggravated felony, and indicates those who have been removed."],[0,"(2) The record under paragraph (1)(C) shall be made available—"],[1,"(A) to inspectors at ports of entry and to border patrol agents at sector headquarters for purposes of immediate identification of any alien who was previously ordered removed and is seeking to reenter the United States, and"],[1,"(B) to officials of the Department of State for use in its automated visa lookout system."],[0,"(3) Upon the request of the governor or chief executive officer of any State, the Service shall provide assistance to State courts in the identification of aliens unlawfully present in the United States pending criminal prosecution."],[0,"(e) Judicial review"],[0,"The Attorney General's discretionary judgment regarding the application of this section shall not be subject to review. No court may set aside any action or decision by the Attorney General under this section regarding the detention or release of any alien or the grant, revocation, or denial of bond or parole."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1226?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 15, 5, 15, 5, 15, 5, 15","2":"passim, 2, 5, 16"},"q":[{"src":"brief","b":0,"text":"pending a decision on whether the alien is to be removed from the United States.","cite":"8 U.S.C. 1226(a)"},{"src":"brief","b":0,"text":"release the alien on * * * bond.","cite":"8 U.S.C. 1226(a)(2)(A)"},{"src":"brief","b":2,"text":"pending a decision on whether the alien is to be re- moved from the United States.","cite":"8 U.S.C. 1226(a)"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"pending a Page Proof Pending Publication decision on whether the alien is to be removed from the United States,","cite":"8 U. S. C. § 1226(a)"},{"src":"argument","who":"Mr. Suri","text":"Chief Justice, and may it please the Court: Respondents are detained under Section 1231, not under Section 1226. In the first place, the text of Section 1231 refers repeatedly to an order of removal or to the aliens who have been ordered removed."},{"src":"argument","who":"Mr. Suri","text":"The claim here is that the government doesn't have the authority to detain the alien unless it has provided bond hearings under Section 1226."},{"src":"argument","who":"Mr. Suri","text":"The Court is reviewing a determination that these aliens are entitled to bond hearings, but that determination depends on the contention that these aliens are detained under Section 1226 rather than Section 1231."}]},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1227-1229c","url":"https://www.law.cornell.edu/uscode/text/8/1227-1229c","by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)","(b)"],"by":{"0":"2, 2"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1230","url":"https://www.law.cornell.edu/uscode/text/8/1230","by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(B)(i)","(a)(2)","(a)(3)","(a)(5)","(a)(6)","(a)(7)","(b)(1)","(b)(1)(C)(iv)","(b)(2)","(b)(2)(E)(vii)","(b)(2)(F)","(b)(3)","(b)(3)(A)","(c)(1)(A)","(c)(2)(A)(i)","(a)(4)","(b)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"passim, passim, 2, 5, 8, 9, 8, 2, 2, 7, 16, 7, 3, 6, 11, passim, 5, 5, 3, 5, 6, 9, 6"},"q":[{"src":"brief","b":0,"text":"finds that an alien has reentered the United States illegally after having been removed * * * under an order of removal, the prior order of removal is reinstated from its original date.","cite":"8 U.S.C. 1231(a)(5)"},{"src":"brief","b":0,"text":"During the removal period, [the Secretary of Homeland Security] shall detain the alien. Under no circumstance during the removal period shall the [Secretary] release [certain criminal aliens].","cite":"8 U.S.C. 1231(a)(2)"},{"src":"brief","b":2,"text":"a risk to the community or unlikely to comply with the order of removal.","cite":"8 U.S.C. 1231(a)(6)"},{"src":"brief","b":2,"text":"unlikely to comply with the order of removal.","cite":"8 U.S.C. 1231(a)(6)"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the `removal period').","cite":"8 U. S. C. § 1231(a)(1)(A)"},{"src":"argument","who":"Mr. Suri","text":"Chief Justice, and may it please the Court: Respondents are detained under Section 1231, not under Section 1226. In the first place, the text of Section 1231 refers repeatedly to an order of removal or to the aliens who have been ordered removed."},{"src":"argument","who":"Mr. Suri","text":"Because, in Section 1231, the words are \"ordered removed.\" It doesn't refer to the practicalities of removal. And even in 1226, although the court of appeals read \"whether the alien is to be removed\" to refer to that practical question, Respondents themselves have abandoned that argument they had --"},{"src":"argument","who":"Mr. Suri","text":"The Court is reviewing a determination that these aliens are entitled to bond hearings, but that determination depends on the contention that these aliens are detained under Section 1226 rather than Section 1231."}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(b)(1)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2","2":"12, 12"},"q":[{"src":"brief","b":2,"text":"filed not later than 30 days after the date of the final order of removal.","cite":"8 U.S.C. 1252(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(3)"],"stext":{"head":"§202. Border, maritime, and transportation responsibilities","paras":[[0,"The Secretary shall be responsible for the following:"],[1,"(1) Preventing the entry of terrorists and the instruments of terrorism into the United States."],[1,"(2) Securing the borders, territorial waters, ports, terminals, waterways, and air, land, and sea transportation systems of the United States, including managing and coordinating those functions transferred to the Department at ports of entry."],[1,"(3) Carrying out the immigration enforcement functions vested by statute in, or performed by, the Commissioner of Immigration and Naturalization (or any officer, employee, or component of the Immigration and Naturalization Service) immediately before the date on which the transfer of functions specified under section 251 of this title takes effect."],[1,"(4) Establishing and administering rules, in accordance with section 236 of this title, governing the granting of visas or other forms of permission, including parole, to enter the United States to individuals who are not a citizen or an alien lawfully admitted for permanent residence in the United States."],[1,"(5) Establishing national immigration enforcement policies and priorities."],[1,"(6) Except as provided in part C of this subchapter, administering the customs laws of the United States."],[1,"(7) Conducting the inspection and related administrative functions of the Department of Agriculture transferred to the Secretary of Homeland Security under section 231 of this title."],[1,"(8) In carrying out the foregoing responsibilities, ensuring the speedy, orderly, and efficient flow of lawful traffic and commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/202?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"7"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"3"}},{"t":"case","label":"Andriasian v. INS","cite":"180 F.3d 1033","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/180/1033/","by":{"1":"6, 30"}},{"t":"case","label":"Arevalo v. Ashcroft","cite":"344 F.3d 1","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/344/1/","by":{"1":"24"}},{"t":"case","label":"Avila-Macias v. Ashcroft","cite":"328 F.3d 108","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/328/108/","by":{"1":"24"}},{"t":"case","label":"Baldwin v. United States","cite":"140 S. Ct. 690","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/690/","sc":1,"by":{"1":"46"}},{"t":"case","label":"Briseno-Sanchez v. Heinauer","cite":"319 F.3d 324","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/319/324/","by":{"1":"25"}},{"t":"case","label":"Castillo v. ICE Field Office Dir.","cite":"907 F. Supp. 2d 1235","y":2012,"court":"W.D. Wash.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/907/1235/","by":{"1":"42"}},{"t":"case","label":"Chay Ixcot v. Holder","cite":"646 F.3d 1202","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/1202/","by":{"1":"25"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"1":"38, 39"},"q":[{"src":"brief","b":1,"text":"reasonable presumption that Congress did not intend the alternative which raises serious constitutional doubts.","cite":"543 U.S. 371, 381"}]},{"t":"case","label":"Concrete Pipe & Products of Cal., Inc. v. Construction Laborers Pension Trust","cite":"508 U.S. 602","y":1993,"id":"1992/91-904","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"due process requires a ‘neutral and detached judge in the first instance.’","cite":"508 U.S. 602, 617"}]},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"1":"38, 44","2":"14, 17, 18, 19, 20"},"q":[{"src":"brief","b":2,"text":"a constitutionally valid aspect of the deportation process.","cite":"538 U.S. 510, 523"},{"src":"brief","b":2,"text":"But when the Government deals with deportable aliens, the Due Process Clause does not require it to employ the least burdensome means to accomplish its goal.","cite":"538 U.S. at 528"}]},{"t":"case","label":"Diouf v. Mukasey","cite":"542 F.3d 1222","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/542/1222/","by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"to afford the government a reasonable amount of time within which to make the travel, consular, and various other administrative arrangements that are necessary to secure removal.","cite":"542 F.3d 1222, 1231"}]},{"t":"case","label":"Duran-Hernandez v. Ashcroft","cite":"348 F.3d 1158","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/1158/","by":{"1":"25"}},{"t":"case","label":"Foucha v. Louisiana","cite":"504 U.S. 71","y":1992,"id":"1991/90-5844","sc":1,"by":{"1":"40"}},{"t":"case","label":"Garcia-Villeda v. Mukasey","cite":"531 F.3d 141","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/531/141/","by":{"1":"24"}},{"t":"case","label":"German Santos v. Warden Pike Cty. Corr. Facility","cite":"965 F.3d 203","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/965/203/","by":{"1":"39"}},{"t":"case","label":"Gomez-Chavez v. INS","cite":"308 F.3d 796","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/308/796/","by":{"1":"25"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"41","2":"13"},"q":[{"src":"brief","b":2,"text":"The canon of constitutional avoidance ‘comes into play only when, after the application of ordinary textual analysis, the statute is found to be susceptible of more than one construction.’","cite":"138 S. Ct. 830, 842"}]},{"t":"case","label":"Jimenez-Morales v. United States Att’y Gen.","cite":"821 F.3d 1307","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1307/","by":{"1":"25"}},{"t":"case","label":"Kansas v. Crane","cite":"534 U.S. 407","y":2002,"id":"2001/00-957","sc":1,"by":{"1":"43"}},{"t":"case","label":"Kim Ho Ma v. Reno","cite":"208 F.3d 815","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/208/815/","by":{"1":"37"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"it is generally clear that ‘shall’ imposes a mandatory duty.","cite":"136 S. Ct. 1969, 1977"}]},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"only when that legal toolkit is empty and the interpretive question still has no single right answer.","cite":"139 S. Ct. at 2415"}]},{"t":"case","label":"Kossov v. INS","cite":"132 F.3d 405","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/132/405/","by":{"1":"6, 30"}},{"t":"case","label":"Kumarasamy v. Attorney Gen. of U.S.","cite":"453 F.3d 169","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/453/169/","by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"are almost never removed from the U.S.","cite":"453 F.3d 169, 171 n.1"}]},{"t":"case","label":"Lopez v. Napolitano","cite":"2014 WL 1091336","y":2014,"court":"E.D. Cal. Mar. 18","by":{"1":"42"}},{"t":"case","label":"Luna-Garcia v. Holder","cite":"777 F.3d 1182","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1182/","by":{"1":"25, 26"},"q":[{"src":"brief","b":1,"text":"the reinstated removal order is not final in the usual legal sense because it cannot be executed until further agency proceedings are complete.","cite":"777 F.3d 1182, 1185"}]},{"t":"case","label":"Martinez v. LaRose","cite":"968 F.3d 555","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/555/","by":{"1":"5, 39"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"by":{"1":"34"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders Of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"by":{"1":"18, 22"},"q":[{"src":"brief","b":1,"text":"‘indicates a command that admits of no discretion on the part of the person instructed to carry out the directive.’","cite":"551 U.S. 644, 661"},{"src":"brief","b":1,"text":"fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"551 U.S. at 666"}]},{"t":"case","label":"Ojeda-Terrazas v. Ashcroft","cite":"290 F.3d 292","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/290/292/","by":{"1":"25"}},{"t":"case","label":"Ortiz-Alfaro v. Holder","cite":"694 F.3d 955","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/955/","by":{"1":"25","2":"12"},"q":[{"src":"brief","b":2,"text":"[t]here are compelling arguments in favor of finding that [the] reinstated removal order is final","cite":"694 F.3d 955, 958"}]},{"t":"case","label":"Padilla v. ICE","cite":"953 F.3d 1134","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/1134/","by":{"1":"39"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"1":"46"}},{"t":"case","label":"Ponce-Osorio v. Johnson","cite":"824 F.3d 502","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/502/","by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"the rights, obligations, and legal consequences of the reinstated removal order are not fully determined until the reasonable fear and withholding of removal proceedings are complete.","cite":"824 F.3d 502, 506"}]},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"1":"34"}},{"t":"case","label":"Sarmiento Cisneros v. United States Att’y Gen.","cite":"381 F.3d 1277","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/381/1277/","by":{"1":"25"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"1":"22"}},{"t":"case","label":"Velasquez-Gabriel v. Crocetti","cite":"263 F.3d 102","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/263/102/","by":{"1":"25"}},{"t":"case","label":"Warner v. Ashcroft","cite":"381 F.3d 534","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/381/534/","by":{"1":"25"}},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"by":{"1":"43","2":"14, 19"},"q":[{"src":"brief","b":2,"text":"as part of the means necessary to give effect to the provisions for the exclusion or expulsion of aliens","cite":"163 U.S. at 235"}]},{"t":"reg","label":"8 C.F.R. § 208.16","url":"https://www.ecfr.gov/current/title-8/section-208.16","by":{"1":"3"}},{"t":"reg","label":"64 Fed. Reg. 8,478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"34"}},{"t":"case","label":"Carlson v. Landon","cite":"342 U.S. 524","y":1952,"id":"scdb/1951-054","sc":1,"by":{"2":"14, 19"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"[f ]inality is variously defined; like many legal terms, its precise meaning depends on context.","cite":"537 U.S. 522, 527"}]},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"[t]he provisions of a text should be interpreted in a way that renders them compatible, not contradictory. There can be no justification for needlessly rendering provisions in conflict if they can be interpreted harmoniously.","cite":"570 U.S. 48, 68"}]},{"t":"case","label":"Reno v. Flores","cite":"507 U.S. 292","y":1993,"id":"1992/91-905","sc":1,"by":{"2":"13, 14, 18"},"q":[{"src":"brief","b":2,"text":"[t]he ‘constitutional doubts’ argument has been the last refuge of many an interpretive lost cause.","cite":"507 U.S. 292, 314 n.9"},{"src":"brief","b":2,"text":"[s]tatutes should be interpreted to avoid serious constitutional doubts, not to eliminate all possible contentions that the statute might be unconstitutional.","cite":"507 U.S. at 314 n.9"}]},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"by":{"2":"16"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"16"}},{"t":"reg","label":"Continued Detention of Aliens Subject to Final Orders of Removal, 66 Fed. Reg. 56,967","url":"https://www.govinfo.gov/link/fr/66/56967","by":{"2":"16"}}]};